/// Result of one `Authentication-Results` method (SPF, DKIM, DMARC).
enum SpamAuthResult {
  pass,
  fail,
  softFail,
  neutral,
  none,

  /// temperror / permerror / policy / unknown.
  other,
}

/// The user's provider's `Authentication-Results` (the top-most header).
class SpamAuthResults {
  /// An `Authentication-Results` header was present at all.
  final bool present;
  final SpamAuthResult? spf;
  final SpamAuthResult? dkim;
  final SpamAuthResult? dmarc;

  const SpamAuthResults({
    required this.present,
    this.spf,
    this.dkim,
    this.dmarc,
  });

  @override
  int get hashCode =>
      present.hashCode ^ spf.hashCode ^ dkim.hashCode ^ dmarc.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SpamAuthResults &&
          runtimeType == other.runtimeType &&
          present == other.present &&
          spf == other.spf &&
          dkim == other.dkim &&
          dmarc == other.dmarc;
}

/// Result of [`Engine::spam_explain`]: the stored verdict and a fresh offline evaluation.
