/// The classifier's label.
enum SpamLabel { ham, unsure, spam }

/// Result of [`Engine::spam_learn`].
class SpamLearnReport {
  final PlatformInt64 id;
  final SpamLabel learned;
  final SpamLabel? previouslyLearned;

  /// Where the message was moved (the junk folder for spam, `INBOX` for "not spam"), when
  /// it was moved. The local row normally keeps its id; it is dropped (and stored again by
  /// the next sync of that folder) only when the server cannot tell the new UID.
  final String? movedTo;
  final int modelSpamMessages;
  final int modelHamMessages;

  /// Fresh verdict under the updated model; its label is the user's.
  final SpamVerdict verdict;

  const SpamLearnReport({
    required this.id,
    required this.learned,
    this.previouslyLearned,
    this.movedTo,
    required this.modelSpamMessages,
    required this.modelHamMessages,
    required this.verdict,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      learned.hashCode ^
      previouslyLearned.hashCode ^
      movedTo.hashCode ^
      modelSpamMessages.hashCode ^
      modelHamMessages.hashCode ^
      verdict.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SpamLearnReport &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          learned == other.learned &&
          previouslyLearned == other.previouslyLearned &&
          movedTo == other.movedTo &&
          modelSpamMessages == other.modelSpamMessages &&
          modelHamMessages == other.modelHamMessages &&
          verdict == other.verdict;
}

/// One line of a spam explanation: a rule hit, a forced label (allowlist, blocklist, signed
/// by a contact) or the user's feedback.
class SpamReason {
  /// Stable code, e.g. `raw_ip_url`, `allowlist`, `signed_by_contact`, `user_feedback`.
  final String code;

  /// Log-odds contribution (0 for forced labels).
  final double weight;
  final String detail;

  const SpamReason({
    required this.code,
    required this.weight,
    required this.detail,
  });

  @override
  int get hashCode => code.hashCode ^ weight.hashCode ^ detail.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SpamReason &&
          runtimeType == other.runtimeType &&
          code == other.code &&
          weight == other.weight &&
          detail == other.detail;
}

/// Per-account spam settings. [`Engine::set_spam_settings`] validates and normalises them
/// (thresholds in 0..1 with unsure ≤ spam, a non-empty folder other than INBOX, lists
/// lower-cased and deduplicated) and returns what was stored.
class SpamSettings {
  /// Classify incoming mail at all.
  final bool enabled;

  /// Probability from which a message is shown as "unsure".
  final double unsureThreshold;

  /// Probability from which a message is spam and moved to the junk folder.
  final double spamThreshold;

  /// Query Spamhaus ZEN/DBL through DNS. Reveals sender IPs and link domains to the
  /// resolver, hence off by default.
  final bool dnsblEnabled;

  /// Folder spam is moved to. The default `Spam` means "the server's junk folder, creating
  /// `Spam` when there is none".
  final String moveToFolder;

  /// Senders (addresses or domains) that are never spam.
  final List<String> allowlist;

  /// Senders (addresses or domains) that are always spam.
  final List<String> blocklist;

  const SpamSettings({
    required this.enabled,
    required this.unsureThreshold,
    required this.spamThreshold,
    required this.dnsblEnabled,
    required this.moveToFolder,
    required this.allowlist,
    required this.blocklist,
  });

  @override
  int get hashCode =>
      enabled.hashCode ^
      unsureThreshold.hashCode ^
      spamThreshold.hashCode ^
      dnsblEnabled.hashCode ^
      moveToFolder.hashCode ^
      allowlist.hashCode ^
      blocklist.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SpamSettings &&
          runtimeType == other.runtimeType &&
          enabled == other.enabled &&
          unsureThreshold == other.unsureThreshold &&
          spamThreshold == other.spamThreshold &&
          dnsblEnabled == other.dnsblEnabled &&
          moveToFolder == other.moveToFolder &&
          allowlist == other.allowlist &&
          blocklist == other.blocklist;
}

/// Model statistics and every account's settings ([`Engine::spam_status`]).
class SpamStatus {
  final int modelSpamMessages;
  final int modelHamMessages;
  final int modelTokens;

  /// 0..1 — how much the Bayes model is trusted right now (it needs some training first).
  final double modelConfidence;
