/// The classifier's answer (mirrors `sealbox_core::Verdict`).
class SpamVerdict {
  final double spamProbability;
  final SpamLabel label;
  final List<SpamReason> reasons;

  /// Raw Bayes log-odds before clamping / confidence scaling.
  final double bayesLogOdds;

  /// 0..1 — how much the Bayes model was trusted.
  final double bayesConfidence;

  /// Sum of the rule weights.
  final double rulesScore;

  /// Final log-odds the probability was derived from.
  final double logOdds;

  const SpamVerdict({
    required this.spamProbability,
    required this.label,
    required this.reasons,
    required this.bayesLogOdds,
    required this.bayesConfidence,
    required this.rulesScore,
    required this.logOdds,
  });

  @override
  int get hashCode =>
      spamProbability.hashCode ^
      label.hashCode ^
      reasons.hashCode ^
      bayesLogOdds.hashCode ^
      bayesConfidence.hashCode ^
      rulesScore.hashCode ^
      logOdds.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SpamVerdict &&
          runtimeType == other.runtimeType &&
          spamProbability == other.spamProbability &&
          label == other.label &&
          reasons == other.reasons &&
          bayesLogOdds == other.bayesLogOdds &&
          bayesConfidence == other.bayesConfidence &&
          rulesScore == other.rulesScore &&
          logOdds == other.logOdds;
}

