/// Event from [`Engine::watch`] (flattened, see [`AuthHint`]).
enum WatchEventKind {
  /// IDLE is active (`folder` set).
  idle,

  /// New mail was synced (`report` set; may be empty if the change was a flag update).
  newMail,

  /// The IDLE timeout elapsed without server activity.
  timeout,
}
